package com.game_manager.gm.workflow; import com.game_manager.gm.common.entity.BaseEntity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="workflow_steps") @Getter @Setter @NoArgsConstructor public class WorkflowStep extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="instance_id",nullable=false)private WorkflowInstance instance;@Column(name="step_key",nullable=false,length=60)private String stepKey;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="assignee_id",length=36)private UUID assigneeId;@Column(name="assignee_role",nullable=false,length=30)private String assigneeRole;@Enumerated(EnumType.STRING)@Column(nullable=false,length=24)private StepStatus status;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="due_at",nullable=false)private Instant dueAt;@Column(name="reminder_at")private Instant reminderAt;@Column(name="reminded_at")private Instant remindedAt;@Column(name="completed_at")private Instant completedAt;}
